export type ConnectEmbeddedPaymentsFeatures = {
  /** Whether to allow capturing and cancelling payment intents. This is `true` by default. */
  capture_payments: boolean;
  /** Whether connected accounts can manage destination charges that are created on behalf of them. This is `false` by default. */
  destination_on_behalf_of_charge_management: boolean;
  /** Whether responding to disputes is enabled, including submitting evidence and accepting disputes. This is `true` by default. */
  dispute_management: boolean;
  /** Whether sending refunds is enabled. This is `true` by default. */
  refund_management: boolean;
};

export type ConnectEmbeddedPayoutsConfig = {
  /** Whether the embedded component is enabled. */
  enabled: boolean;
  features: ConnectEmbeddedPayoutsFeatures;
};

export type ConnectEmbeddedPayoutsFeatures = {
  /** Whether Stripe user authentication is disabled. This value can only be `true` for accounts where `controller.requirement_collection` is `application` for the account. The default value is the opposite of the `external_account_collection` value. For example, if you don't set `external_account_collection`, it defaults to `true` and `disable_stripe_user_authentication` defaults to `false`. */
  disable_stripe_user_authentication: boolean;
  /** Whether to allow payout schedule to be changed. Defaults to `true` when `controller.losses.payments` is set to `stripe` for the account, otherwise `false`. */
  edit_payout_schedule: boolean;
  /** Whether external account collection is enabled. This feature can only be `false` for accounts where you’re responsible for collecting updated information when requirements are due or change, like Custom accounts. The default value for this feature is `true`. */
  external_account_collection: boolean;
  /** Whether to allow creation of instant payouts. The default value is `enabled` when Stripe is responsible for negative account balances, and `use_dashboard_rules` otherwise. */
  instant_payouts: boolean;
  /** Whether to allow creation of standard payouts. Defaults to `true` when `controller.losses.payments` is set to `stripe` for the account, otherwise `false`. */
  standard_payouts: boolean;
};

/** Stripe needs to collect certain pieces of information about each account created. These requirements can differ depending on the account's country. The Country Specs API makes these rules available to your integration.  You can also view the information from this API call as [an online guide](/docs/connect/required-verification-information). */
export type CountrySpec = {
  /** The default currency for this country. This applies to both payment methods and bank accounts. */
  default_currency: string;
  /** Unique identifier for the object. Represented as the ISO country code for this country. */
  id: string;
  /** String representing the object's type. Objects of the same type share the same value. */
  object: "country_spec";
  /** Currencies that can be accepted in the specific country (for transfers). */
  supported_bank_account_currencies: { [key: string]: (string)[] | undefined };
  /** Currencies that can be accepted in the specified country (for payments). */
  supported_payment_currencies: (string)[];
  /** Payment methods available in the specified country. You may need to enable some payment methods (e.g., [ACH](https://stripe.com/docs/ach)) on your account before they appear in this list. The `stripe` payment method refers to [charging through your platform](https://stripe.com/docs/connect/destination-charges). */
  supported_payment_methods: (string)[];
  /** Countries that can accept transfers from the specified country. */
  supported_transfer_countries: (string)[];
  verification_fields: CountrySpecVerificationFields;
};

export type CountrySpecVerificationFieldDetails = {
  /** Additional fields which are only required for some users. */
  additional: (string)[];
  /** Fields which every account must eventually provide. */
  minimum: (string)[];
};

export type CountrySpecVerificationFields = {
  company: CountrySpecVerificationFieldDetails;
  individual: CountrySpecVerificationFieldDetails;
};

/** A coupon contains information about a percent-off or amount-off discount you might want to apply to a customer. Coupons may be applied to [subscriptions](https://api.stripe.com#subscriptions), [invoices](https://api.stripe.com#invoices), [checkout sessions](https://docs.stripe.com/api/checkout/sessions), [quotes](https://api.stripe.com#quotes), and more. Coupons do not work with conventional one-off [charges](/api/charges/create) or [payment intents](https://docs.stripe.com/api/payment_intents). */
export type Coupon = {
  /** Amount (in the `currency` specified) that will be taken off the subtotal of any invoices for this customer. */
  amount_off?: number | null;
  applies_to?: CouponAppliesTo;
  /** Time at which the object was created. Measured in seconds since the Unix epoch. */
  created: number;
  /** If `amount_off` has been set, the three-letter [ISO code for the currency](https://stripe.com/docs/currencies) of the amount to take off. */
  currency?: string | null;
  /** Coupons defined in each available currency option. Each key must be a three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html) and a [supported currency](https://stripe.com/docs/currencies). */
  currency_options?: { [key: string]: CouponCurrencyOption | undefined };
  /** One of `forever`, `once`, or `repeating`. Describes how long a customer who applies this coupon will get the discount. */
  duration: "forever" | "once" | "repeating";
  /** If `duration` is `repeating`, the number of months the coupon applies. Null if coupon `duration` is `forever` or `once`. */
  duration_in_months?: number | null;
  /** Unique identifier for the object. */
  id: string;
  /** If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`. */
  livemode: boolean;
  /** Maximum number of times this coupon can be redeemed, in total, across all customers, before it is no longer valid. */
  max_redemptions?: number | null;
  /** Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. */
  metadata?: { [key: string]: string | undefined } | null;
  /** Name of the coupon displayed to customers on for instance invoices or receipts. */
  name?: string | null;
  /** String representing the object's type. Objects of the same type share the same value. */
  object: "coupon";
  /** Percent that will be taken off the subtotal of any invoices for this customer for the duration of the coupon. For example, a coupon with percent_off of 50 will make a $ (or local equivalent)100 invoice $ (or local equivalent)50 instead. */
  percent_off?: number | null;
  /** Date after which the coupon can no longer be redeemed. */
  redeem_by?: number | null;
  /** Number of times this coupon has been applied to a customer. */
  times_redeemed: number;
  /** Taking account of the above properties, whether this coupon can still be applied to a customer. */
  valid: boolean;
};

export type CouponAppliesTo = {
  /** A list of product IDs this coupon applies to */
  products: (string)[];
};

export type CouponCurrencyOption = {
  /** Amount (in the `currency` specified) that will be taken off the subtotal of any invoices for this customer. */
  amount_off: number;
};

export type CreditBalance = {
  available_balance: BillingCreditGrantsResourceAmount;
  ledger_balance: BillingCreditGrantsResourceAmount;
};

/** Issue a credit note to adjust an invoice's amount after the invoice is finalized.  Related guide: [Credit notes](https://docs.stripe.com/billing/invoices/credit-notes) */
export type CreditNote = {
  /** The integer amount in cents (or local equivalent) representing the total amount of the credit note, including tax. */
  amount: number;
  /** This is the sum of all the shipping amounts. */
  amount_shipping: number;
  /** Time at which the object was created. Measured in seconds since the Unix epoch. */
  created: number;
  /** Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies). */
  currency: string;
  /** ID of the customer. */
  customer: string | Customer | DeletedCustomer;
  /** ID of the account representing the customer. */
  customer_account?: string | null;
  /** Customer balance transaction related to this credit note. */
  customer_balance_transaction?: string | CustomerBalanceTransaction | null;
  /** The integer amount in cents (or local equivalent) representing the total amount of discount that was credited. */
  discount_amount: number;
  /** The aggregate amounts calculated per discount for all line items. */
  discount_amounts: (DiscountsResourceDiscountAmount)[];
  /** The date when this credit note is in effect. Same as `created` unless overwritten. When defined, this value replaces the system-generated 'Date of issue' printed on the credit note PDF. */
  effective_at?: number | null;
  /** Unique identifier for the object. */
  id: string;
  /** ID of the invoice. */
  invoice: string | Invoice;
  /** Line items that make up the credit note */
  lines: { data: (CreditNoteLineItem)[]; has_more: boolean; object: "list"; url: string };
  /** If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`. */
  livemode: boolean;
  /** Customer-facing text that appears on the credit note PDF. */
  memo?: string | null;
  /** Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. */
  metadata?: { [key: string]: string | undefined } | null;
  /** A unique number that identifies this particular credit note and appears on the PDF of the credit note and its associated invoice. */
  number: string;
  /** String representing the object's type. Objects of the same type share the same value. */
  object: "credit_note";
  /** Amount that was credited outside of Stripe. */
  out_of_band_amount?: number | null;
  /** The link to download the PDF of the credit note. */
  pdf: string;
  /** The amount of the credit note that was refunded to the customer, credited to the customer's balance, credited outside of Stripe, or any combination thereof. */
  post_payment_amount: number;
  /** The amount of the credit note by which the invoice's `amount_remaining` and `amount_due` were reduced. */
  pre_payment_amount: number;
  /** The pretax credit amounts (ex: discount, credit grants, etc) for all line items. */
  pretax_credit_amounts: (CreditNotesPretaxCreditAmount)[];
  /** Reason for issuing this credit note, one of `duplicate`, `fraudulent`, `order_change`, or `product_unsatisfactory` */
  reason?: "duplicate" | "fraudulent" | "order_change" | "product_unsatisfactory" | null;
  /** Refunds related to this credit note. */
  refunds: (CreditNoteRefund)[];
  /** The details of the cost of shipping, including the ShippingRate applied to the invoice. */
  shipping_cost?: InvoicesResourceShippingCost | null;
  /** Status of this credit note, one of `issued` or `void`. Learn more about [voiding credit notes](https://docs.stripe.com/billing/invoices/credit-notes#voiding). */
  status: "issued" | "void";
  /** The integer amount in cents (or local equivalent) representing the amount of the credit note, excluding exclusive tax and invoice level discounts. */
  subtotal: number;
  /** The integer amount in cents (or local equivalent) representing the amount of the credit note, excluding all tax and invoice level discounts. */
  subtotal_excluding_tax?: number | null;
  /** The integer amount in cents (or local equivalent) representing the total amount of the credit note, including tax and all discount. */
  total: number;
  /** The integer amount in cents (or local equivalent) representing the total amount of the credit note, excluding tax, but including discounts. */
  total_excluding_tax?: number | null;
  /** The aggregate tax information for all line items. */
  total_taxes?: (BillingBillResourceInvoicingTaxesTax)[] | null;
  /** Type of this credit note, one of `pre_payment` or `post_payment`. A `pre_payment` credit note means it was issued when the invoice was open. A `post_payment` credit note means it was issued when the invoice was paid. */
  type: "mixed" | "post_payment" | "pre_payment";
  /** The time that the credit note was voided. */
  voided_at?: number | null;
};

/** The credit note line item object */
export type CreditNoteLineItem = {
  /** The integer amount in cents (or local equivalent) representing the gross amount being credited for this line item, excluding (exclusive) tax and discounts. */
  amount: number;
  /** Description of the item being credited. */
  description?: string | null;
  /** The integer amount in cents (or local equivalent) representing the discount being credited for this line item. */
  discount_amount: number;
  /** The amount of discount calculated per discount for this line item */
  discount_amounts: (DiscountsResourceDiscountAmount)[];
  /** Unique identifier for the object. */
  id: string;
  /** ID of the invoice line item being credited */
  invoice_line_item?: string;
  /** If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`. */
  livemode: boolean;
  /** Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. */
  metadata?: { [key: string]: string | undefined } | null;
  /** String representing the object's type. Objects of the same type share the same value. */
  object: "credit_note_line_item";
  /** The pretax credit amounts (ex: discount, credit grants, etc) for this line item. */
  pretax_credit_amounts: (CreditNotesPretaxCreditAmount)[];
  /** The number of units of product being credited. */
  quantity?: number | null;
  /** The tax rates which apply to the line item. */
  tax_rates: (TaxRate)[];
  /** The tax information of the line item. */
  taxes?: (BillingBillResourceInvoicingTaxesTax)[] | null;
  /** The type of the credit note line item, one of `invoice_line_item` or `custom_line_item`. When the type is `invoice_line_item` there is an additional `invoice_line_item` property on the resource the value of which is the id of the credited line item on the invoice. */
  type: "custom_line_item" | "invoice_line_item";
  /** The cost of each unit of product being credited. */
  unit_amount?: number | null;
  /** Same as `unit_amount`, but contains a decimal value with at most 12 decimal places. */
  unit_amount_decimal?: string | null;
};

export type CreditNoteRefund = {
  /** Amount of the refund that applies to this credit note, in cents (or local equivalent). */
  amount_refunded: number;
  /** The PaymentRecord refund details associated with this credit note refund. */
  payment_record_refund?: CreditNotesPaymentRecordRefund | null;
  /** ID of the refund. */
  refund: string | Refund;
  /** Type of the refund, one of `refund` or `payment_record_refund`. */
  type?: "payment_record_refund" | "refund" | null;
};

export type CreditNotesPaymentRecordRefund = {
  /** ID of the payment record. */
  payment_record: string;
  /** ID of the refund group. */
  refund_group: string;
};

export type CreditNotesPretaxCreditAmount = {
  /** The amount, in cents (or local equivalent), of the pretax credit amount. */
  amount: number;
  /** The credit balance transaction that was applied to get this pretax credit amount. */
  credit_balance_transaction?: string | BillingCreditBalanceTransaction;
  /** The discount that was applied to get this pretax credit amount. */
  discount?: string | Discount | DeletedDiscount;
  /** Type of the pretax credit amount referenced. */
  type: "credit_balance_transaction" | "discount";
};

export type CreditedItemsInvoiceLineItems = {
  /** The invoice id for the debited line item(s). */
  invoice: string;
  /** IDs of the debited invoice line item(s) on the invoice that correspond to the credit proration. */
  invoice_line_items: (string)[];
};

export type CurrencyOption = {
  /** When set, provides configuration for the amount to be adjusted by the customer during Checkout Sessions and Payment Links. */
  custom_unit_amount?: CustomUnitAmount | null;
  /** Only required if a [default tax behavior](https://docs.stripe.com/tax/products-prices-tax-categories-tax-behavior#setting-a-default-tax-behavior-(recommended)) was not provided in the Stripe Tax settings. Specifies whether the price is considered inclusive of taxes or exclusive of taxes. One of `inclusive`, `exclusive`, or `unspecified`. Once specified as either `inclusive` or `exclusive`, it cannot be changed. */
  tax_behavior?: "exclusive" | "inclusive" | "unspecified" | null;
  /** Each element represents a pricing tier. This parameter requires `billing_scheme` to be set to `tiered`. See also the documentation for `billing_scheme`. */
  tiers?: (PriceTier)[];
  /** The unit amount in cents (or local equivalent) to be charged, represented as a whole integer if possible. Only set if `billing_scheme=per_unit`. */
  unit_amount?: number | null;
  /** The unit amount in cents (or local equivalent) to be charged, represented as a decimal string with at most 12 decimal places. Only set if `billing_scheme=per_unit`. */
  unit_amount_decimal?: string | null;
};

export type CustomLogo = {
  /** Content type of the Dashboard-only CustomPaymentMethodType logo. */
  content_type?: string | null;
  /** URL of the Dashboard-only CustomPaymentMethodType logo. */
  url: string;
};

export type CustomUnitAmount = {
  /** The maximum unit amount the customer can specify for this item. */
  maximum?: number | null;
  /** The minimum unit amount the customer can specify for this item. Must be at least the minimum charge amount. */
  minimum?: number | null;
  /** The starting unit amount which can be updated by the customer. */
  preset?: number | null;
};

/** This object represents a customer of your business. Use it to [create recurring charges](https://docs.stripe.com/invoicing/customer), [save payment](https://docs.stripe.com/payments/save-during-payment) and contact information, and track payments that belong to the same customer. */
export type Customer = {
  /** The customer's address. */
  address?: Address | null;
  /** The current balance, if any, that's stored on the customer in their default currency. If negative, the customer has credit to apply to their next invoice. If positive, the customer has an amount owed that's added to their next invoice. The balance only considers amounts that Stripe hasn't successfully applied to any invoice. It doesn't reflect unpaid invoices. This balance is only taken into account after invoices finalize. For multi-currency balances, see [invoice_credit_balance](https://docs.stripe.com/api/customers/object#customer_object-invoice_credit_balance). */
  balance?: number;
  /** The customer's business name. */
  business_name?: string;
  /** The current funds being held by Stripe on behalf of the customer. You can apply these funds towards payment intents when the source is "cash_balance". The `settings[reconciliation_mode]` field describes if these funds apply to these payment intents manually or automatically. */
  cash_balance?: CashBalance | null;
  /** Time at which the object was created. Measured in seconds since the Unix epoch. */
  created: number;
  /** Three-letter [ISO code for the currency](https://stripe.com/docs/currencies) the customer can be charged in for recurring billing purposes. */
  currency?: string | null;
  /** The ID of an Account representing a customer. You can use this ID with any v1 API that accepts a customer_account parameter. */
  customer_account?: string | null;
  /** ID of the default payment source for the customer.  If you use payment methods created through the PaymentMethods API, see the [invoice_settings.default_payment_method](https://docs.stripe.com/api/customers/object#customer_object-invoice_settings-default_payment_method) field instead. */
  default_source?: string | BankAccount | Card | Source | null;
  /** Tracks the most recent state change on any invoice belonging to the customer. Paying an invoice or marking it uncollectible via the API will set this field to false. An automatic payment failure or passing the `invoice.due_date` will set this field to `true`.  If an invoice becomes uncollectible by [dunning](https://docs.stripe.com/billing/automatic-collection), `delinquent` doesn't reset to `false`.  If you care whether the customer has paid their most recent subscription invoice, use `subscription.status` instead. Paying or marking uncollectible any customer invoice regardless of whether it is the latest invoice for a subscription will always set this field to `false`. */
  delinquent?: boolean | null;
  /** An arbitrary string attached to the object. Often useful for displaying to users. */
  description?: string | null;
  /** Describes the current discount active on the customer, if there is one. */
  discount?: Discount | null;
  /** The customer's email address. */
  email?: string | null;
  /** Unique identifier for the object. */
  id: string;
  /** The customer's individual name. */
  individual_name?: string;
  /** The current multi-currency balances, if any, that's stored on the customer. If positive in a currency, the customer has a credit to apply to their next invoice denominated in that currency. If negative, the customer has an amount owed that's added to their next invoice denominated in that currency. These balances don't apply to unpaid invoices. They solely track amounts that Stripe hasn't successfully applied to any invoice. Stripe only applies a balance in a specific currency to an invoice after that invoice (which is in the same currency) finalizes. */
  invoice_credit_balance?: { [key: string]: number | undefined };
  /** The prefix for the customer used to generate unique invoice numbers. */
  invoice_prefix?: string | null;
  invoice_settings?: InvoiceSettingCustomerSetting;
  /** If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`. */
  livemode: boolean;
  /** Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. */
  metadata?: { [key: string]: string | undefined };
  /** The customer's full name or business name. */
  name?: string | null;
  /** The suffix of the customer's next invoice number (for example, 0001). When the account uses account level sequencing, this parameter is ignored in API requests and the field omitted in API responses. */
  next_invoice_sequence?: number;
  /** String representing the object's type. Objects of the same type share the same value. */
  object: "customer";
  /** The customer's phone number. */
  phone?: string | null;
  /** The customer's preferred locales (languages), ordered by preference. */
  preferred_locales?: (string)[] | null;
  /** Mailing and shipping address for the customer. Appears on invoices emailed to this customer. */
  shipping?: Shipping | null;
  /** The customer's payment sources, if any. */
  sources?: { data: (BankAccount | Card | Source)[]; has_more: boolean; object: "list"; url: string };
  /** The customer's current subscriptions, if any. */
  subscriptions?: { data: (Subscription)[]; has_more: boolean; object: "list"; url: string };
  tax?: CustomerTax;
  /** Describes the customer's tax exemption status, which is `none`, `exempt`, or `reverse`. When set to `reverse`, invoice and receipt PDFs include the following text: **"Reverse charge"**. */
  tax_exempt?: "exempt" | "none" | "reverse" | null;
  /** The customer's tax IDs. */
  tax_ids?: { data: (TaxId)[]; has_more: boolean; object: "list"; url: string };
  /** ID of the test clock that this customer belongs to. */
  test_clock?: string | TestHelpersTestClock | null;
};

