export type IssuingCardFraudWarning = {
  /** Timestamp of the most recent fraud warning. */
  started_at?: number | null;
  /** The type of fraud warning that most recently took place on this card. This field updates with every new fraud warning, so the value changes over time. If populated, cancel and reissue the card. */
  type?: "card_testing_exposure" | "fraud_dispute_filed" | "third_party_reported" | "user_indicated_fraud" | null;
};

export type IssuingCardGooglePay = {
  /** Google Pay Eligibility */
  eligible: boolean;
  /** Reason the card is ineligible for Google Pay */
  ineligible_reason?: "missing_agreement" | "missing_cardholder_contact" | "unsupported_region" | null;
};

export type IssuingCardLifecycleConditions = {
  /** The card is automatically cancelled when it makes this number of non-zero payment authorizations and transactions. The count includes penny authorizations, but doesn't include non-payment actions, such as authorization advice. */
  payment_count: number;
};

export type IssuingCardLifecycleControls = {
  cancel_after: IssuingCardLifecycleConditions;
};

export type IssuingCardShipping = {
  address: Address;
  /** Address validation details for the shipment. */
  address_validation?: IssuingCardShippingAddressValidation | null;
  /** The delivery company that shipped a card. */
  carrier?: "dhl" | "fedex" | "royal_mail" | "usps" | null;
  /** Additional information that may be required for clearing customs. */
  customs?: IssuingCardShippingCustoms | null;
  /** A unix timestamp representing a best estimate of when the card will be delivered. */
  eta?: number | null;
  /** Recipient name. */
  name: string;
  /** The phone number of the receiver of the shipment. Our courier partners will use this number to contact you in the event of card delivery issues. For individual shipments to the EU/UK, if this field is empty, we will provide them with the phone number provided when the cardholder was initially created. */
  phone_number?: string | null;
  /** Whether a signature is required for card delivery. This feature is only supported for US users. Standard shipping service does not support signature on delivery. The default value for standard shipping service is false and for express and priority services is true. */
  require_signature?: boolean | null;
  /** Shipment service, such as `standard` or `express`. */
  service: "express" | "priority" | "standard";
  /** The delivery status of the card. */
  status?: "canceled" | "delivered" | "failure" | "pending" | "returned" | "shipped" | "submitted" | null;
  /** A tracking number for a card shipment. */
  tracking_number?: string | null;
  /** A link to the shipping carrier's site where you can view detailed information about a card shipment. */
  tracking_url?: string | null;
  /** Packaging options. */
  type: "bulk" | "individual";
};

export type IssuingCardShippingAddressValidation = {
  /** The address validation capabilities to use. */
  mode: "disabled" | "normalization_only" | "validation_and_normalization";
  /** The normalized shipping address. */
  normalized_address?: Address | null;
  /** The validation result for the shipping address. */
  result?: "indeterminate" | "likely_deliverable" | "likely_undeliverable" | null;
};

export type IssuingCardShippingCustoms = {
  /** A registration number used for customs in Europe. See [https://www.gov.uk/eori](https://www.gov.uk/eori) for the UK and [https://ec.europa.eu/taxation_customs/business/customs-procedures-import-and-export/customs-procedures/economic-operators-registration-and-identification-number-eori_en](https://ec.europa.eu/taxation_customs/business/customs-procedures-import-and-export/customs-procedures/economic-operators-registration-and-identification-number-eori_en) for the EU. */
  eori_number?: string | null;
};

