  paypal?: SetupIntentPaymentMethodOptionsPaypal | SetupIntentTypeSpecificPaymentMethodOptionsClient;
  payto?: SetupIntentPaymentMethodOptionsPayto | SetupIntentTypeSpecificPaymentMethodOptionsClient;
  pix?: SetupIntentPaymentMethodOptionsPix | SetupIntentTypeSpecificPaymentMethodOptionsClient;
  sepa_debit?: SetupIntentPaymentMethodOptionsSepaDebit | SetupIntentTypeSpecificPaymentMethodOptionsClient;
